<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\ValueObject\Accessor\UserAccessTemporalCodeRegisterCodeAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAccessTemporalCodeRegisterCodeAccessor trait.
 *
 * Covers null default, string/VO assignment via withRegisterCode,
 * getRegisterCode/registerCode accessors, and isRegisterCodeChanged with/without original.
 */
class UserAccessTemporalCodeRegisterCodeAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRegisterCode creates a new instance with the RegisterCode set
     * from a string value, and getRegisterCode returns the primitive string.
     */
    public function testWithRegisterCodeFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRegisterCodeAccessorUnitTest();

        // Act
        $result = $holder->withRegisterCode('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getRegisterCode());
    }
    /**
     * Asserts that withregisterCode has access to the value object
     * from a string value, and getRegisterCode returns the primitive string.
     */
    public function testWithRegisterCodeFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRegisterCodeAccessorUnitTest();

        // Act
        $result = $holder->withRegisterCode('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->registerCode()->value());
    }
    public function testChangedRegisterCode(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRegisterCodeAccessorUnitTest();
        $original = $holder->withRegisterCode('one');
        $same = $holder->withRegisterCode('one');
        $modified = $holder->withRegisterCode('other');

        // Act
        $unchanged = $holder->isRegisterCodeChanged();
        $withSame = $original->isRegisterCodeChanged($same);
        $withDiferent = $original->isRegisterCodeChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserAccessTemporalCodeRegisterCodeAccessorUnitTest
{
    use UserAccessTemporalCodeRegisterCodeAccessor;
}
